INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9e8fa08b-f55d-5576-91f5-cdb193e22c37', 'Address', 'Maintain Address records', 'Create, find and maintain Address records. The list shows every Address you have access to — select a row to open it, or use New to add one. Each row is a single Address, described by 17 fields.

Id is unique: no two Address records may share the same value, and a save that would duplicate one is rejected. Address Type, Line1, Is Primary, Status and Country must be filled in before the record can be saved.

Every Address points at Party, Person, Organization, Country, State Province and City. Choose the linked record from the lookup on those fields rather than typing an identifier. Location refers back to Address, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Address then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Address with no rules or workflows attached is marked Final immediately.', 'map-pin', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a9bd6474-0b63-561e-ad80-ba7dd9e9b4c0', 'bus_address', 'Address', 'Reusable address master data with explicit rules for ownership, primary selection, lifecycle, and historical transaction evidence. Address is reusable master data, but an address printed on an issued invoice, shipment, order, or other historical document is transaction evidence and must remain reproducible even if the master address changes. Supports Party, Organization, Customer, Supplier, Location, order, fulfillment, invoicing, taxation, shipping, reporting, and integration workflows. Party and Location may reuse an Address. Operational documents should resolve the effective address at transaction time and preserve the result where historical reproduction is required. Address create/update → validate country/geography → validate Party/Location dependency → select effective address → transaction captures address evidence → later master-data changes affect future selection only. Active → inactive/retired. Retirement prevents new normal use but does not remove historical references or snapshots. A Customer changes its billing address. The Customer master now points to the new active address, while already issued Invoices retain the address effective when they were issued.', 'map-pin', 'A', FALSE, FALSE, FALSE, TRUE, '9e8fa08b-f55d-5576-91f5-cdb193e22c37', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b33b2b5d-032d-590e-8270-ddcdcaaf9b65', '9e8fa08b-f55d-5576-91f5-cdb193e22c37', 'a9bd6474-0b63-561e-ad80-ba7dd9e9b4c0', 'Address', 'Shows one Address at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Party, Person, Organization, Country, State Province and City are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6191f642-801d-51f6-a143-257ea837beba', 'a9bd6474-0b63-561e-ad80-ba7dd9e9b4c0', 'id', 'Id', 'The address id of the address: an identifier the business records on it. Entered or maintained when a address is created or changed; shown on its form and available to search and reports. Read together with the address''s other fields and its relationships; it is not meaningful on its own. Required: a address cannot be understood without its address id.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
