VALUES ('b132f56f-3762-5020-9a1e-da3097173d9d', '0dcd6716-64b6-5a77-8b85-68a4ccc3fd07', '60fe1a9d-fd8c-5f04-ae61-445d845fb235', '37492e3a-9d51-5c01-b0f6-fc430be10fc3', 'Country', 'The country the division belongs to. Chosen first; the divisions offered are those of that country. Every state or province belongs to exactly one country. A city and an address are narrowed by the country before the state. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
