INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d16648e0-db54-550b-9e0b-5aa5ddc6b9be', 'Media Content', 'Maintain Media Content records', 'Create, find and maintain Media Content records. The list shows every Media Content you have access to — select a row to open it, or use New to add one. Each row is a single Media Content, described by 6 fields.

Id and Content Code are unique: no two Media Content records may share the same value, and a save that would duplicate one is rejected. Content Code, Title, Content Type and Status must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Media Content then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Media Content with no rules or workflows attached is marked Final immediately.', 'image', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eae9be1c-0052-58fe-b52b-9584ae30fdbd', 'bus_media_content', 'Media Content', 'Represents a media entity called MediaContent within the CEDM business model. MediaContent is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate MediaContent records. The entity participates in a wider business graph through relationships with Organization, Document, MediaRight. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical MediaContent record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'image', 'A', FALSE, FALSE, FALSE, TRUE, 'd16648e0-db54-550b-9e0b-5aa5ddc6b9be', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d5539c22-08f0-51c5-8fd8-c4638c9d2632', 'd16648e0-db54-550b-9e0b-5aa5ddc6b9be', 'eae9be1c-0052-58fe-b52b-9584ae30fdbd', 'Media Content', 'Shows one Media Content at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
