INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9a6d1954-2dc0-5039-934b-7b8962f01880', 'Unit Of Measure Category', 'Maintain Unit Of Measure Category records', 'Create, find and maintain Unit Of Measure Category records. The list shows every Unit Of Measure Category you have access to — select a row to open it, or use New to add one. Each row is a single Unit Of Measure Category, described by 6 fields.

Id and Code are unique: no two Unit Of Measure Category records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Unit Of Measure Category then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Unit Of Measure Category with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('23792e08-7a86-557a-aec3-21eba3b17fef', 'bus_unit_of_measure_category', 'Unit Of Measure Category', 'The values of unit of measure category, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '9a6d1954-2dc0-5039-934b-7b8962f01880', 'U', TRUE, 'system', 'system', NOW(), NOW())
