VALUES ('397295b2-b2ce-590d-89c3-156efb43f620', 'bus_media_right_status', 'Media Right Status', 'The values of media right status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'd4d3b2e3-4b76-512e-8683-727f1252cca5', 'U', TRUE, 'system', 'system', NOW(), NOW())
